package itmo.scala.hw2.task1

import org.scalatest.concurrent.{Signaler, TimeLimitedTests}
import org.scalatest.flatspec.AnyFlatSpec
import org.scalatest.matchers.should.Matchers
import org.scalatest.time.Span
import org.scalatest.time.SpanSugar._

class FibonacciSpec extends AnyFlatSpec with Matchers with TimeLimitedTests {
  "Fibonacci.fib" should "correctly work for first nums" in {
    Fibonacci.fib(0) shouldBe BigInt(0)
    Fibonacci.fib(1) shouldBe BigInt(1)
    Fibonacci.fib(2) shouldBe BigInt(1)
    Fibonacci.fib(3) shouldBe BigInt(2)
    Fibonacci.fib(4) shouldBe BigInt(3)
    Fibonacci.fib(5) shouldBe BigInt(5)
    Fibonacci.fib(6) shouldBe BigInt(8)
    Fibonacci.fib(7) shouldBe BigInt(13)
    Fibonacci.fib(8) shouldBe BigInt(21)
    Fibonacci.fib(9) shouldBe BigInt(34)
    Fibonacci.fib(10) shouldBe BigInt(55)
  }

  it should "return 0 for negative nums" in {
    Fibonacci.fib(-1) shouldBe 0
  }

  it should "not throw StackOverflowError for big nums" in {
    val expected = BigInt(
      ""
    )

    Fibonacci.fib(10000) shouldBe expected
  }

  "Fibonacci.fibDiv" should "correctly work" in {
    Fibonacci.fibDiv(2, 0) shouldBe BigInt(0)
    Fibonacci.fibDiv(2, 1) shouldBe BigInt(2)
    Fibonacci.fibDiv(2, 2) shouldBe BigInt(8)
    Fibonacci.fibDiv(3, 0) shouldBe BigInt(0)
    Fibonacci.fibDiv(3, 1) shouldBe BigInt(3)
    Fibonacci.fibDiv(3, 2) shouldBe BigInt(21)
    Fibonacci.fibDiv(10, 2) shouldBe BigInt(832040)

    Fibonacci.fibDiv(3, 3) shouldBe BigInt("144")
    Fibonacci.fibDiv(13, 3) shouldBe BigInt("10946")
    Fibonacci.fibDiv(15, 3) shouldBe BigInt("1548008755920")
    Fibonacci.fibDiv(7, 5) shouldBe BigInt("102334155")
    Fibonacci.fibDiv(10, 10) shouldBe BigInt("9969216677189303386214405760200")
    Fibonacci.fibDiv(100, 2) shouldBe BigInt("222232244629420445529739893461909967206666939096499764990979600")
  }

  override def timeLimit: Span               = 10.seconds
  override val defaultTestSignaler: Signaler = _ => {
    println("FibonacciSpec: Test timeout")
    System.exit(1)
  }
}
